command:
// ==========================================
// LUNAS WIRKUNG: GRAUSAMES SPIEL (APHASMA)
//
// - genau ein lebendiges Ziel
// - nicht auf sich selbst
// - Reichweite 8 Schritt
// - Schaden: 2W6 + QS × 2
// - Ziel muss weniger LeP als Wirkender besitzen
// - Ziel kann nicht unter 5 LeP sinken
// - Schadensverarbeitung über Block 18
// - LeP- und Regelprüfungen intern
// - eine gemeinsame Karte + roter GM-Button
// ==========================================

(async function () {
    const macroUuid = this?.uuid || null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Schaden?.GMKarte || !globalThis.DSK?.Schaden?.LeP ||
        !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
        !globalThis.DSK?.Target?.Merken || !globalThis.DSK?.Target?.Actor ||
        !globalThis.DSK?.Wesen?.IstLebendig || !globalThis.DSK?.Geometrie?.Distanz ||
        !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
        !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
        !globalThis.DSK?.GabenUI?.GMMakroButton || !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Schaden?.GMKarte || !DSK_FW?.Schaden?.LeP ||
        !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
        !DSK_FW?.Target?.Merken || !DSK_FW?.Target?.Actor ||
        !DSK_FW?.Wesen?.IstLebendig || !DSK_FW?.Geometrie?.Distanz ||
        !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
        !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
        !DSK_FW?.GabenUI?.GMMakroButton || !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
        !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
    ) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework inklusive Block 18 wurde nicht vollständig geladen!");

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Grausames Spiel", vollerName = "Grausames Spiel (Aphasma)", ahne = "Aphasma";
    const flagKey = "pendingGrausamesSpielAphasma", reichweite = 8, minimumLeP = 5;

    const beschreibung =
        `Eine Vielzahl kleiner, unerklärlicher Risse und innerer Blutungen durchzieht den Körper des Opfers.` +
        `<br><br>Das Ziel muss weniger LeP als der Wirkende besitzen. Aphasmas Regeln verhindern, ` +
        `dass Grausames Spiel das Ziel unter <b>${minimumLeP} LeP</b> senkt.`;

    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
        if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
    };

    // +++ 3 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++

    const verarbeiteAnfrage = async (casterActor, daten) => {
        if (!casterActor || !daten || !DSK_FW.Schaden.IstAktiverGM()) return false;

        if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) {
            ui.notifications.warn("Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum Wirkenden.");
            return false;
        }

        if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
            ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
            return false;
        }

        const casterToken = DSK_FW.Token.Finde(casterActor, daten.casterTokenId, daten.casterTokenUuid);
        const targetActor = await DSK_FW.Target.Actor(daten.target);
        const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
        const targetName = daten.target?.name || targetActor?.name || "Unbekanntes Ziel";
        const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
        const wuerfelSumme = Math.max(0, Math.floor(Number(daten.wuerfelSumme) || 0));
        const bonus = Math.max(0, Math.floor(Number(daten.bonus) || qs * 2));
        const gesamtSchaden = Math.max(0, Math.floor(Number(daten.gesamtSchaden) || wuerfelSumme + bonus));
        const schadensText = `${wuerfelSumme} aus 2W6 + ${bonus} (QS ${qs} × 2) = ${gesamtSchaden} TP`;

        if (!casterToken) {
            ui.notifications.warn(`Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde nicht gefunden!`);
            return false;
        }

        const misserfolg = async grund => {
            await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
                messageId: daten.messageId, gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
                ziele: [], misserfolge: [{ name: targetName, grund }], dauerText: "sofort", erfolgreich: false
            });
            return true;
        };

        if (!targetActor) return misserfolg("Ziel wurde nicht gefunden");
        if (!DSK_FW.Wesen.IstLebendig(targetActor)) return misserfolg("Kein lebendiges Wesen");
        if (targetActor.uuid === casterActor.uuid || targetActor.id === casterActor.id) {
            return misserfolg("Wirkender kann nicht sein eigenes Ziel sein");
        }

        const targetToken = DSK_FW.Token.Finde(targetActor, daten.target?.tokenId, daten.target?.tokenUuid);

        if (targetToken && DSK_FW.Geometrie.Distanz(casterToken, targetToken) > reichweite) {
            return misserfolg(`Außerhalb der Reichweite von ${reichweite} Schritt`);
        }

        if (DSK_FW.Schaden.LeP(targetActor) >= DSK_FW.Schaden.LeP(casterActor)) {
            return misserfolg("Das Ziel besitzt nicht weniger LeP als der Wirkende");
        }

        // +++ 3.1 - KOMPAKTE SCHADENSKARTE ÜBER BLOCK 18 ++++++

        const schadensKarte = await DSK_FW.Schaden.GMKarte({
            key: `grausamesSpiel-${daten.messageId}`, titel: "Grausames Spiel – Schaden", ahne,
            zusammenfassung: `${targetName} – erkannter Schaden`,
            beschreibung:
                `<b>${casterName}</b> wirkt Grausames Spiel auf <b>${targetName}</b>.` +
                `<br><br><b>Würfelberechnung:</b> ${schadensText}`,

            modus: "fest", basis: gesamtSchaden,
            ziele: [{ uuid: targetActor.uuid, name: targetName }],

            minimumLeP, vergleichsActorUuid: casterActor.uuid,
            zielMussSchwaecherSein: true, grenzenTitel: "Aphasmas Grenze",
            lepDetailsVerbergen: true, regelDetailsVerbergen: true,

            limitText:
                `Das Ziel erleidet weniger Schaden als gedacht, da Aphasma eingreift, ` +
                `um die Regeln von Grausames Spiel durchzusetzen.`,

            abschlussText:
                `Aphasmas grausames Spiel kann das Ziel nicht unter ${minimumLeP} LeP senken.`,

            vollTrefferText:
                `<b>${casterName}</b>s Grausames Spiel hat seine volle Wirkung entfaltet ` +
                `und schlägt mit voller Härte bei <b>${targetName}</b> zu.`,

            buttonText: "Schaden anwenden",
            bestaetigungsTitel: "Grausames Spiel – Schaden angewendet",
            quelleUuid: casterActor.uuid
        });

        const erfolgreich = Boolean(schadensKarte);

        // +++ 3.2 - GEMEINSAME GABENKARTE AKTUALISIEREN ++++++

        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId: daten.messageId, gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
            ziele: erfolgreich ? [{
                name:
                    `${targetName}<br>` +
                    `<span style="font-size:.9em;color:#555;">Schaden: ${schadensText}</span>`,
                rolle: "Betroffenes Ziel"
            }] : [],
            misserfolge: erfolgreich ? [] : [{
                name: targetName,
                grund: "Schadenskarte konnte nicht erstellt werden"
            }],
            dauerText: "sofort", erfolgreich
        });

        if (erfolgreich) ui.notifications.info("Luna sagt 🌙: Die Schadenskarte für Grausames Spiel wurde erstellt.");
        else ui.notifications.error("Luna sagt 🌙: Die Schadenskarte konnte nicht erstellt werden!");

        return true;
    };

    // +++ 4 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++

    if (game.user.isGM) {
        const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

        if (anfragen.length) {
            for (const anfrageActor of anfragen) {
                const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
                if (!daten) continue;
                if (await verarbeiteAnfrage(anfrageActor, daten)) {
                    await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
                }
            }
            return;
        }
    }

    // +++ 5 - WIRKENDER + QS ++++++++++++++++++++++++++++++++++

    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor)
                .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
            game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) || null;
    }

    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!");
    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");
    }

    const casterToken = DSK_FW.Token.Finde(casterActor);
    if (!casterToken) {
        return ui.notifications.warn("Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!");
    }

    const casterName = DSK_FW.ResolveTokenName(casterActor);
    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor, gabenName,
        suchbegriffe: ["Grausames Spiel Probe", "Grausames Spiel"],
        testDataObj: typeof testData !== "undefined" ? testData : null,
        fallback: 0, protokollieren: true
    });

    if (qs <= 0) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn("Luna sagt 🌙: Die Probe ist fehlgeschlagen oder die Qualitätsstufe konnte nicht ermittelt werden!");
    }

    // +++ 6 - ZIELPRÜFUNG +++++++++++++++++++++++++++++++++++++

    const targets = Array.from(game.user.targets || []);

    if (targets.length !== 1) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn("Luna sagt 🌙: Bitte markiere genau ein Ziel!");
    }

    const targetToken = targets[0], targetActor = targetToken?.actor;
    const targetName = targetToken?.name || targetActor?.name || "Unbekanntes Ziel";

    if (!targetActor) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn("Luna sagt 🌙: Das gewählte Ziel besitzt keinen gültigen Charakterbogen!");
    }

    if (targetActor.uuid === casterActor.uuid || targetActor.id === casterActor.id) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn("Luna sagt 🌙: Du kannst das grausame Spiel nicht an dir selbst wirken!");
    }

    if (!DSK_FW.Wesen.IstLebendig(targetActor)) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName, ahne, beschreibung, wirkender: casterName, ziele: [],
            misserfolge: [{ name: targetName, grund: "Kein lebendiges Wesen" }],
            dauerText: "sofort", gmBereich: false, angewendet: true, erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    if (DSK_FW.Geometrie.Distanz(casterToken, targetToken) > reichweite) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName, ahne, beschreibung, wirkender: casterName, ziele: [],
            misserfolge: [{ name: targetName, grund: `Außerhalb der Reichweite von ${reichweite} Schritt` }],
            dauerText: "sofort", gmBereich: false, angewendet: true, erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    const targetDaten = DSK_FW.Target.Merken(targetToken);

    if (!targetDaten) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Das Ziel konnte nicht gespeichert werden!");
    }

    // +++ 7 - SCHADEN AUSWÜRFELN ++++++++++++++++++++++++++++++

    const bonus = qs * 2;
    const schadensWurf = await new Roll(`2d6 + ${bonus}`).evaluate();
    const gesamtSchaden = Math.max(0, Math.floor(Number(schadensWurf.total) || 0));

    const wuerfelSumme = Math.max(
        0,
        Math.floor(
            Number(schadensWurf.dice?.[0]?.total) ||
            gesamtSchaden - bonus
        )
    );

    const schadensText =
        `${wuerfelSumme} aus 2W6 + ${bonus} ` +
        `(QS ${qs} × 2) = ${gesamtSchaden} TP`;

    // +++ 8 - GEMEINSAME KARTE + ROTER GM-BUTTON +++++++++++++

    const gmLink = DSK_FW.GabenUI.GMMakroButton(
        macroUuid, "Schaden prüfen und anwenden",
        "Das Makro muss durch die Spielleitung ausgeführt werden."
    );

    const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
        ziele: [{
            name:
                `${targetName}<br>` +
                `<span style="font-size:.9em;color:#555;">Schaden: ${schadensText}</span>`,
            rolle: "Betroffenes Ziel"
        }],
        misserfolge: [], dauerText: "sofort",
        gmLink, gmBereich: !game.user.isGM,
        anfragenderUserId: game.user.id
    });

    if (!nachricht) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!");
    }

    // +++ 9 - ANFRAGEDATEN ++++++++++++++++++++++++++++++++++++

    const anfrageDaten = {
        casterUuid: casterActor.uuid, casterName,
        casterTokenId: casterToken.id,
        casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
        target: targetDaten, qs, bonus, wuerfelSumme, gesamtSchaden,
        sceneId: canvas.scene?.id || null, requestedByUserId: game.user.id,
        messageId: nachricht.id, macroUuid, erstellt: Date.now()
    };

    // +++ 10 - GM DIREKT ODER ANFRAGE SPEICHERN +++++++++++++++

    if (game.user.isGM) {
        await verarbeiteAnfrage(casterActor, anfrageDaten);
        await raeumeQSAuf(casterActor);
        return;
    }

    await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);
    await raeumeQSAuf(casterActor);

    ui.notifications.info("Luna sagt 🌙: Grausames Spiel wurde bei der Spielleitung beantragt.");

}).call(this);
